// Checkout conversion fix: ensure paidEvents increment on successful payment
const { log } = require('../utils/logger');
const { incrementPaidEvents } = require('../revenue/revenueTracker');

module.exports = function(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    if (res.statusCode === 200 && body && body.success && body.paymentId) {
      log('Checkout conversion detected, incrementing paidEvents');
      incrementPaidEvents();
    }
    return originalJson(body);
  };
  next();
};
